SELECT 'gongkao', '条件变化综合', 'kp-eng-e-mix', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "条件变化综合"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "人数在变，每个人的效率也在变。双重突变叠加。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "最惨烈的变化：“开工 5 天后，不仅调走了 2 人，留下的人因为疲劳，效率还下降了 10%”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式（总效率的拆解）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "此时不能简单令每人效率为1。必须把“人数”和“单人效率”分开赋值。"}]}, {"type": "katexBlock", "attrs": {"content": "P_{阶段} = 当前人数 \\times 当前单人效率"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[遇到人数与单人效率双重变化] --> B[先处理单人效率的百分比变化, 赋 P旧 和 P新]\nB --> C[结合初始人数, 算出 W总 = 初始人数 × P旧 × 总时间]\nC --> D[第一阶段: 已完成 = 初始人数 × P旧 × 耗时]\nD --> E[第二阶段: 剩余W / (变动后人数 × P新) = 新耗时]\nE --> F[相加出结果]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 10 人原计划 20 天完工。干了 5 天后调走 2 人，为赶工期，剩下的人采用新工艺，单人效率提升了 25%。问最终提前或延后几天？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋单人效率：提升 25%(1/4)，令 P旧 = 4，P新 = 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算总量 W：10 人 × 每天干 4 × 20 天。W = 800。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算已完工：10 人 × 每天干 4 × 5 天 = 200。剩余 600。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算突变后阶段：剩 8 人。每个人效率变为 5。当前总效率 = 8 × 5 = 40。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求新耗时：600 ÷ 40 = 15 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比对计划：实际总用时 5 + 15 = 20 天。与原计划相同。答案：不提前也不延后。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "乘法少乘一项：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在计算新总效率时，最容易忘记乘当前的人数，或者忘记乘单人的新效率。在草稿纸上必须写出 `8人 × 5效率/人` 这种带单位的算式，防止大脑短路。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把“单人效率”和“人数”看成长方形的长和宽，总效率就是面积。双重变化就是长宽同时被拉伸或压缩。"}]}]}$$ AS jsonb), NULL, '条件变化综合的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "条件变化综合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_e_mix", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
